#include <vector>
#include <iostream>

struct Heavy { int x = 0; Heavy() { /* Expensive setup */ } };

int main() {
    // Method 1: Size Initialization (calls 100 constructors)
    std::vector<Heavy> v1(100);
    std::cout << "V1 Size: " << v1.size() 
              << " Capacity: " << v1.capacity() << std::endl;

    // Method 2: Reservation (calls 0 constructors)
    std::vector<Heavy> v2;
    v2.reserve(100); 
    std::cout << "V2 Size: " << v2.size() 
              << " Capacity: " << v2.capacity() << std::endl;

    // Only reserve() avoids construction overhead if elements are later inserted.
}
